import { readdirSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

// One page per advisory (execution plan G-04), from the advisories in this repository; each has a Markdown twin at
// /advisories/<id>.md (site/public, generated by packages/core/test/publish.test.ts).
const dir = fileURLToPath(new URL("../../advisories/", import.meta.url));

const NAMES: Record<string, string> = {
  anthropic: "Anthropic", github: "GitHub", google: "Google", "google-gemini": "Gemini", hubspot: "HubSpot",
  "meta-graph": "Meta", openai: "OpenAI", quickbooks: "QuickBooks", reddit: "Reddit", salesforce: "Salesforce",
  shopify: "Shopify", slack: "Slack", stripe: "Stripe", twilio: "Twilio", x: "X", xero: "Xero",
};

/** The page body: values come in through Vue bindings ($params), which escape them; only the H1 is literal, as VitePress takes the page title from it. */
const BODY = "\n\n<dl class=\"shapi-advisory\">\n  <dt>Provider</dt><dd>{{ $params.a.providerName }}</dd>\n  <dt>Endpoint</dt><dd><code>{{ $params.a.endpoint.method }} {{ $params.a.endpoint.path }}</code></dd>\n  <dt>Effective</dt><dd>{{ $params.a.effectiveDate }}</dd>\n  <dt>Severity</dt><dd>{{ $params.a.severity }}</dd>\n  <dt>Change</dt><dd>{{ $params.a.changeClass }}</dd>\n  <dt>Status</dt><dd>{{ $params.a.status }}<span v-if=\"$params.a.status === 'unverified'\"> (secondary reports only; SHAPI does not open fix PRs for it)</span></dd>\n  <dt v-if=\"$params.a.recipeId\">Automatic fix</dt><dd v-if=\"$params.a.recipeId\"><code>{{ $params.a.recipeId }}</code></dd>\n</dl>\n\n## What changed\n\n{{ $params.a.summary }}\n\n## What to do\n\n{{ $params.a.migrationNote }}\n\n## Sources\n\n<ul>\n  <li v-if=\"$params.a.publishedNotice\"><a :href=\"$params.a.publishedNotice.url\">Provider notice</a><span v-if=\"$params.a.publishedNotice.date\"> ({{ $params.a.publishedNotice.date }})</span></li>\n  <li v-for=\"s in $params.a.sources.filter((s) => s !== $params.a.publishedNotice?.url)\" :key=\"s\"><a :href=\"s\">{{ s }}</a></li>\n</ul>\n\n## Check your code\n\n```bash\nnpx shapi-cli scan .\n```\n\n`shapi scan` lists the call sites this change affects; `shapi fix` repairs them test-first when the advisory has an automatic fix. [All advisories](/advisories) · <a :href=\"`/advisories/${$params.id}.md`\">Markdown</a> · <a :href=\"`/osv/${$params.id}.json`\">OSV</a> · <a :href=\"`https://github.com/SriVarshini09/shapi-advisories/blob/main/advisories/${$params.id}.json`\">JSON</a>\n";
const escape = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/[{}*_`[\]#\\]/g, (c) => `&#${c.charCodeAt(0)};`);

export default {
  watch: [`${dir}*.json`],
  paths() {
    return readdirSync(dir)
      .filter((f) => f.endsWith(".json"))
      .map((f) => JSON.parse(readFileSync(`${dir}${f}`, "utf8")) as { id: string; provider: string; title: string; summary: string; migrationNote: string; endpoint: { method: string; path: string }; effectiveDate: string; severity: string; changeClass: string; status: string; recipeId?: string; sources: string[]; publishedNotice: { date: string | null; url: string } | null })
      .map((a) => ({ params: { id: a.id, title: a.title, a: { ...a, providerName: NAMES[a.provider] ?? a.provider } }, content: `# ${escape(a.title)}${BODY}` }));
  },
};
